SELECT DATE_TRUNC('MONTH', shipped_date) AS activity_month, DATE_TRUNC('QUARTER', shipped_date) AS quarter_start, COUNT(*) FILTER (WHERE status = 'LOST') AS lost_rows, COUNT(*) FILTER (WHERE status = 'IN_TRANSIT') AS in_transit_rows, APPROX_PERCENTILE(cost, ARRAY(0.25, 0.5, 0.75)) AS cost_quartiles FROM shipments GROUP BY ROLLUP (DATE_TRUNC('MONTH', shipped_date), DATE_TRUNC('QUARTER', shipped_date)) HAVING in_transit_rows > 1 ORDER BY in_transit_rows
